describe("wave 445: Elven Ambush (create a token for each <Subtype> you control)", () => {
  const compile = (name: string, oracleText: string) =>
    compileOracleCard({
      oracleId: name.toLowerCase().replace(/[^a-z]+/g, "-"),
      name,
      manaCost: "{3}{G}",
      typeLine: "Instant",
      power: null,
      toughness: null,
      printedKeywords: [],
      imageUrl: "",
      oracleText,
    });

  it("compiles the tribal count onto the token as perControlledSubtype", () => {
    const compiled = compile("Elven Ambush", "Create a 1/1 green Elf Warrior creature token for each Elf you control.");
    expect(compiled.notes).toEqual([]);
    expect(compiled.definition.effects).toEqual([
      {
        kind: "create_token",
        ownerId: "controller",
        name: "Elf Warrior",
        typeLine: "Creature — Elf Warrior Token",
        power: 1,
        toughness: 1,
        colors: ["G"],
        perControlledSubtype: "elf",
      },
    ]);
  });

  const put = (game: GameState, ownerId: string, definition: CardDefinition) => {
    game.definitions[definition.id] = definition;
    const card = createCardInstance({ definitionId: definition.id, ownerId, zone: "battlefield" });
    card.summoningSick = false;
    game.cards[card.id] = card;
    game.players.find((entry) => entry.id === ownerId)!.zones.battlefield.push(card.id);
    return card.id;
  };
  const elf = (name: string) => createCardDefinition({ name, typeLine: "Creature — Elf Druid", manaCost: "{G}", power: 1, toughness: 1 });
  const bear = () => createCardDefinition({ name: "Bear", typeLine: "Creature — Bear", manaCost: "{1}{G}", power: 2, toughness: 2 });

  it("creates one token per Elf you control, ignoring non-Elves and opponents' Elves", () => {
    const { game, p1, p2 } = twoPlayers();
    fillLibraries(game, 20);
    put(game, p1.id, elf("Llanowar"));
    put(game, p1.id, elf("Fyndhorn"));
    put(game, p1.id, elf("Elvish Mystic"));
    put(game, p1.id, bear()); // a non-Elf is not counted
    put(game, p2.id, elf("Opposing Elf")); // an opponent's Elf is not counted
    const before = game.players.find((e) => e.id === p1.id)!.zones.battlefield.length;

    const effects = compile("Elven Ambush", "Create a 1/1 green Elf Warrior creature token for each Elf you control.").definition.effects;
    const after = applyEffects(
      game,
      bindCardEffects(game, effects, { controllerId: p1.id, sourceId: game.players.find((e) => e.id === p1.id)!.zones.battlefield[0]!, targets: [], targetRequirements: [] }),
    );
    const battlefield = after.players.find((e) => e.id === p1.id)!.zones.battlefield;
    const tokens = battlefield
      .map((id) => after.cards[id])
      .filter((c) => c?.isToken && after.definitions[c.definitionId]?.name === "Elf Warrior");
    expect(tokens).toHaveLength(3);
    expect(battlefield.length).toBe(before + 3);
  });
});

describe("wave 446: Voldaren Estate ({1} less to activate per Subtype you control)", () => {
  it("compiles the tribal activation discount onto the ability", () => {
    const estate = compileOracleCard({
      oracleId: "voldaren-estate",
      name: "Voldaren Estate",
      manaCost: "",
      typeLine: "Land",
      power: null,
      toughness: null,
      printedKeywords: [],
      imageUrl: "",
      oracleText:
        "{T}: Add {C}.\n{5}, {T}: Create a Blood token. This ability costs {1} less to activate for each Vampire you control.",
    });
    expect(estate.notes).toEqual([]);
    const paid = estate.definition.activated.find((a) => a.manaCost === "{5}");
    expect(paid?.subtypeDiscount).toBe("vampire");
  });

  const estateDef = () =>
    createCardDefinition({
      name: "Estate",
      typeLine: "Land",
      activated: [
        {
          tap: true,
          manaCost: "{5}",
          subtypeDiscount: "vampire",
          effects: [{ kind: "draw", playerId: "controller", count: 1 }],
          targetRequirements: [],
        },
      ],
    });
  const vampire = () => createCardDefinition({ name: "Vampire", typeLine: "Creature — Vampire", manaCost: "{1}{B}", power: 2, toughness: 2 });

  const setup = (vampires: number, mana: number) => {
    const { game, p1 } = twoPlayers();
    fillLibraries(game, 10);
    const land = estateDef();
    game.definitions[land.id] = land;
    const landCard = createCardInstance({ definitionId: land.id, ownerId: p1.id, zone: "battlefield" });
    game.cards[landCard.id] = landCard;
    p1.zones.battlefield.push(landCard.id);
    const vDef = vampire();
    game.definitions[vDef.id] = vDef;
    for (let i = 0; i < vampires; i += 1) {
      const v = createCardInstance({ definitionId: vDef.id, ownerId: p1.id, zone: "battlefield" });
      game.cards[v.id] = v;
      p1.zones.battlefield.push(v.id);
    }
    game.players.find((p) => p.id === p1.id)!.mana.G = mana;
    return { game, p1, landId: landCard.id };
  };

  it("discounts {5} to {3} with two Vampires and resolves", () => {
    const { game, p1, landId } = setup(2, 3);
    const handBefore = game.players.find((p) => p.id === p1.id)!.zones.hand.length;
    const next = applyAction(game, { kind: "activate_ability", playerId: p1.id, cardId: landId, abilityIndex: 0 });
    if (next.stack.length > 0) {
      const resolved = resolveTopOfStack(next);
      expect(resolved.players.find((p) => p.id === p1.id)!.zones.hand.length).toBe(handBefore + 1);
    }
    expect(next.cards[landId]?.tapped).toBe(true);
  });

  it("is not free — two Vampires and only {2} cannot pay the reduced {3}", () => {
    const { game, p1, landId } = setup(2, 2);
    expect(() =>
      applyAction(game, { kind: "activate_ability", playerId: p1.id, cardId: landId, abilityIndex: 0 }),
    ).toThrow();
  });

  it("scales with Vampire count — no Vampires means the full {5}", () => {
    const { game, p1, landId } = setup(0, 3);
    expect(() =>
      applyAction(game, { kind: "activate_ability", playerId: p1.id, cardId: landId, abilityIndex: 0 }),
    ).toThrow();
  });

  it("round trips subtypeDiscount through serialization (guards the field lists)", () => {
    const { game } = twoPlayers();
    const land = estateDef();
    game.definitions[land.id] = land;
    const round = parseGameState(serializeGameState(game));
    expect(round.definitions[land.id]?.activated?.[0]?.subtypeDiscount).toBe("vampire");
  });
});

describe("wave 447: X-loyalty cost (Tezzeret the Seeker's -X)", () => {
  const searchEffect = {
    kind: "search_library" as const,
    playerId: "controller" as const,
    filter: { types: ["artifact"], maxManaValueX: true },
    destination: "battlefield" as const,
    count: 1,
  };

  it("compiles a -X: ability with xLoyaltyCost and reads X into the search", () => {
    const compiled = compileOracleCard({
      oracleId: "seeker",
      name: "Seeker",
      manaCost: "{3}{U}",
      typeLine: "Legendary Planeswalker — Tezzeret",
      power: null,
      toughness: null,
      printedKeywords: [],
      imageUrl: "",
      loyalty: "4",
      oracleText:
        "−X: Search your library for an artifact card with mana value X or less, put it onto the battlefield, then shuffle.",
    });
    expect(compiled.notes).toEqual([]);
    expect(compiled.definition.loyaltyAbilities).toEqual([
      { cost: 0, xLoyaltyCost: true, effects: [searchEffect], targetRequirements: [] },
    ]);
  });

  const walkerDef = () =>
    createCardDefinition({
      name: "Seeker",
      typeLine: "Legendary Planeswalker — Tezzeret",
      loyalty: 4,
      loyaltyAbilities: [
        { cost: 0, xLoyaltyCost: true, effects: [searchEffect], targetRequirements: [] },
      ],
    });
  const mainPhase = (game: GameState, id: string) => {
    game.turn.activePlayerId = id;
    game.turn.phase = "precombatMain";
    game.turn.step = "precombatMain";
    game.priorityPlayerId = id;
  };
  const putWalker = (game: GameState, ownerId: string) => {
    const def = walkerDef();
    game.definitions[def.id] = def;
    const card = createCardInstance({ definitionId: def.id, ownerId, zone: "battlefield" });
    card.counters["loyalty"] = 4;
    game.cards[card.id] = card;
    game.players.find((e) => e.id === ownerId)!.zones.battlefield.push(card.id);
    mainPhase(game, ownerId);
    return card.id;
  };
  const putLibrary = (game: GameState, ownerId: string, name: string, cost: string) => {
    const def = createCardDefinition({ name, typeLine: "Artifact", manaCost: cost });
    game.definitions[def.id] = def;
    const card = createCardInstance({ definitionId: def.id, ownerId, zone: "library" });
    game.cards[card.id] = card;
    game.players.find((e) => e.id === ownerId)!.zones.library.push(card.id);
    return card.id;
  };

  it("pays exactly X loyalty when activated", () => {
    const { game, p1 } = twoPlayers();
    const walkerId = putWalker(game, p1.id);
    putLibrary(game, p1.id, "Filler", "{1}");
    const next = applyAction(game, {
      kind: "activate_loyalty",
      playerId: p1.id,
      cardId: walkerId,
      abilityIndex: 0,
      xValue: 2,
    });
    expect(next.cards[walkerId]?.counters["loyalty"]).toBe(2);
  });

  it("refuses an X larger than the loyalty on the walker", () => {
    const { game, p1 } = twoPlayers();
    const walkerId = putWalker(game, p1.id);
    expect(() =>
      applyAction(game, { kind: "activate_loyalty", playerId: p1.id, cardId: walkerId, abilityIndex: 0, xValue: 5 }),
    ).toThrow();
  });

  it("refuses activation with no X announced", () => {
    const { game, p1 } = twoPlayers();
    const walkerId = putWalker(game, p1.id);
    expect(() =>
      applyAction(game, { kind: "activate_loyalty", playerId: p1.id, cardId: walkerId, abilityIndex: 0 }),
    ).toThrow();
  });

  it("threads X into the search — only artifacts of mana value <= X are offered", () => {
    const { game, p1 } = twoPlayers();
    const walkerId = putWalker(game, p1.id);
    const cheapId = putLibrary(game, p1.id, "Cheap", "{2}");
    const dearId = putLibrary(game, p1.id, "Dear", "{5}");
    let next = applyAction(game, {
      kind: "activate_loyalty",
      playerId: p1.id,
      cardId: walkerId,
      abilityIndex: 0,
      xValue: 2,
    });
    next = resolveTopOfStack(next);
    const prompt = next.prompts[0];
    expect(prompt?.kind).toBe("search_library");
    const legal = legalSearchIds(next, prompt!);
    expect(legal).toContain(cheapId);
    expect(legal).not.toContain(dearId);
  });

  it("round trips xLoyaltyCost through serialization", () => {
    const { game } = twoPlayers();
    const def = walkerDef();
    game.definitions[def.id] = def;
    const round = parseGameState(serializeGameState(game));
    expect(round.definitions[def.id]?.loyaltyAbilities?.[0]?.xLoyaltyCost).toBe(true);
  });
});

describe("wave 448: Untap up to two target artifacts (Tezzeret the Seeker's +1)", () => {
  it("compiles two optional untap slots", () => {
    const compiled = compileOracleCard({
      oracleId: "seeker-plus",
      name: "Seeker",
      manaCost: "{3}{U}{U}",
      typeLine: "Legendary Planeswalker — Tezzeret",
      power: null,
      toughness: null,
      printedKeywords: [],
      imageUrl: "",
      loyalty: "4",
      oracleText: "+1: Untap up to two target artifacts.",
    });
    expect(compiled.notes).toEqual([]);
    expect(compiled.definition.loyaltyAbilities).toEqual([
      {
        cost: 1,
        effects: [
          { kind: "untap", cardId: { type: "chosen", index: 0 } },
          { kind: "untap", cardId: { type: "chosen", index: 1 } },
        ],
        targetRequirements: [
          { kind: "artifact", optional: true },
          { kind: "artifact", optional: true },
        ],
      },
    ]);
  });

  const mainPhase = (game: GameState, id: string) => {
    game.turn.activePlayerId = id;
    game.turn.phase = "precombatMain";
    game.turn.step = "precombatMain";
    game.priorityPlayerId = id;
  };
  const walkerDef = () =>
    createCardDefinition({
      name: "Seeker",
      typeLine: "Legendary Planeswalker — Tezzeret",
      loyalty: 4,
      loyaltyAbilities: [
        {
          cost: 1,
          effects: [
            { kind: "untap", cardId: { type: "chosen", index: 0 } },
            { kind: "untap", cardId: { type: "chosen", index: 1 } },
          ],
          targetRequirements: [
            { kind: "artifact", optional: true },
            { kind: "artifact", optional: true },
          ],
        },
      ],
    });
  const putWalker = (game: GameState, ownerId: string) => {
    const def = walkerDef();
    game.definitions[def.id] = def;
    const card = createCardInstance({ definitionId: def.id, ownerId, zone: "battlefield" });
    card.counters["loyalty"] = 4;
    game.cards[card.id] = card;
    game.players.find((e) => e.id === ownerId)!.zones.battlefield.push(card.id);
    mainPhase(game, ownerId);
    return card.id;
  };
  const putTappedArtifact = (game: GameState, ownerId: string, name: string) => {
    const def = createCardDefinition({ name, typeLine: "Artifact", manaCost: "{2}" });
    game.definitions[def.id] = def;
    const card = createCardInstance({ definitionId: def.id, ownerId, zone: "battlefield" });
    card.tapped = true;
    game.cards[card.id] = card;
    game.players.find((e) => e.id === ownerId)!.zones.battlefield.push(card.id);
    return card.id;
  };

  it("untaps two chosen artifacts and adds loyalty", () => {
    const { game, p1 } = twoPlayers();
    const walkerId = putWalker(game, p1.id);
    const a1 = putTappedArtifact(game, p1.id, "Mox A");
    const a2 = putTappedArtifact(game, p1.id, "Mox B");
    let next = applyAction(game, {
      kind: "activate_loyalty",
      playerId: p1.id,
      cardId: walkerId,
      abilityIndex: 0,
      targets: [
        { type: "creature", cardId: a1 },
        { type: "creature", cardId: a2 },
      ],
    });
    expect(next.cards[walkerId]?.counters["loyalty"]).toBe(5);
    next = resolveTopOfStack(next);
    expect(next.cards[a1]?.tapped).toBe(false);
    expect(next.cards[a2]?.tapped).toBe(false);
  });

  it("permits untapping just one (the second slot is optional)", () => {
    const { game, p1 } = twoPlayers();
    const walkerId = putWalker(game, p1.id);
    const a1 = putTappedArtifact(game, p1.id, "Mox A");
    const a2 = putTappedArtifact(game, p1.id, "Mox B");
    let next = applyAction(game, {
      kind: "activate_loyalty",
      playerId: p1.id,
      cardId: walkerId,
      abilityIndex: 0,
      targets: [{ type: "creature", cardId: a1 }],
    });
    next = resolveTopOfStack(next);
    expect(next.cards[a1]?.tapped).toBe(false);
    expect(next.cards[a2]?.tapped).toBe(true);
  });
});

describe("wave 449: mass-animate your artifacts (Tezzeret the Seeker's -5)", () => {
  it("compiles Tezzeret the Seeker in full (all three abilities)", () => {
    const compiled = compileOracleCard({
      oracleId: "tezzeret-the-seeker",
      name: "Tezzeret the Seeker",
      manaCost: "{3}{U}{U}",
      typeLine: "Legendary Planeswalker — Tezzeret",
      power: null,
      toughness: null,
      printedKeywords: [],
      imageUrl: "",
      loyalty: "4",
      oracleText:
        "+1: Untap up to two target artifacts.\n−X: Search your library for an artifact card with mana value X or less, put it onto the battlefield, then shuffle.\n−5: Artifacts you control become artifact creatures with base power and toughness 5/5 until end of turn.",
    });
    expect(compiled.notes).toEqual([]);
    expect(compiled.definition.loyaltyAbilities).toHaveLength(3);
    expect(compiled.definition.loyaltyAbilities?.[2]).toEqual({
      cost: -5,
      effects: [
        { kind: "animate_controlled_until_eot", playerId: "controller", cardType: "artifact", power: 5, toughness: 5 },
      ],
      targetRequirements: [],
    });
  });

  const put = (game: GameState, ownerId: string, definition: CardDefinition) => {
    game.definitions[definition.id] = definition;
    const card = createCardInstance({ definitionId: definition.id, ownerId, zone: "battlefield" });
    card.summoningSick = false;
    game.cards[card.id] = card;
    game.players.find((entry) => entry.id === ownerId)!.zones.battlefield.push(card.id);
    return card.id;
  };
  const artifact = (name: string) => createCardDefinition({ name, typeLine: "Artifact", manaCost: "{1}" });

  it("turns your artifacts into 5/5 artifact creatures, sparing non-artifacts and opponents' artifacts", () => {
    const { game, p1, p2 } = twoPlayers();
    fillLibraries(game, 10);
    const mox = put(game, p1.id, artifact("Mox"));
    const relic = put(game, p1.id, artifact("Relic"));
    const bear = put(game, p1.id, createCardDefinition({ name: "Bear", typeLine: "Creature — Bear", manaCost: "{1}{G}", power: 2, toughness: 2 }));
    const foreign = put(game, p2.id, artifact("Foreign Mox"));

    const effects = [
      { kind: "animate_controlled_until_eot", playerId: "controller", cardType: "artifact", power: 5, toughness: 5 },
    ] as const;
    const after = applyEffects(
      game,
      bindCardEffects(game, effects as unknown as CardEffect[], { controllerId: p1.id, sourceId: mox, targets: [], targetRequirements: [] }),
    );

    // Your artifacts are now 5/5 creatures (still artifacts).
    expect(computedCard(after, mox)?.power).toBe(5);
    expect(computedCard(after, mox)?.toughness).toBe(5);
    expect(characteristicsOf(after, mox).types).toContain("creature");
    expect(characteristicsOf(after, mox).types).toContain("artifact");
    expect(computedCard(after, relic)?.power).toBe(5);
    // A creature you control is untouched by an artifact-only animate.
    expect(computedCard(after, bear)?.power).toBe(2);
    // An opponent's artifact is not yours to animate.
    expect(characteristicsOf(after, foreign).types).not.toContain("creature");
  });

  it("round trips the mass-animate effect", () => {
    const { game } = twoPlayers();
    const def = createCardDefinition({
      name: "Seeker",
      typeLine: "Legendary Planeswalker — Tezzeret",
      loyalty: 4,
      loyaltyAbilities: [
        {
          cost: -5,
          effects: [
            { kind: "animate_controlled_until_eot", playerId: "controller", cardType: "artifact", power: 5, toughness: 5 },
          ],
          targetRequirements: [],
        },
      ],
    });
    game.definitions[def.id] = def;
    const round = parseGameState(serializeGameState(game));
    expect(round.definitions[def.id]?.loyaltyAbilities?.[0]?.effects).toEqual([
      { kind: "animate_controlled_until_eot", playerId: "controller", cardType: "artifact", power: 5, toughness: 5 },
    ]);
  });
});

