describe("wave 475: Colossal Grave-Reaver — mill a creature, then put it onto the battlefield", () => {
  const compileReaver = () =>
    compileOracleCard({
      oracleId: "colossal-grave-reaver", name: "Colossal Grave-Reaver", manaCost: "{6}{B}{G}",
      typeLine: "Creature — Dragon", power: "6", toughness: "6", printedKeywords: [], imageUrl: "",
      oracleText:
        "Flying\nWhenever this creature enters or attacks, mill three cards.\n" +
        "Whenever one or more creature cards are put into your graveyard from your library, put one of them onto the battlefield.",
    });

  it("compiles flying, the enter/attacks mill, and the mill-to-battlefield reanimator", () => {
    const c = compileReaver();
    expect(c.notes).toEqual([]);
    expect(c.definition.keywords).toContain("flying");
    expect(c.definition.triggers?.map((t) => t.event)).toEqual([
      "enter_battlefield", "attacks", "graveyard_from_elsewhere",
    ]);
    expect(c.definition.triggers?.[2]).toMatchObject({
      subjectFilter: { types: ["creature"] },
      effects: [{ kind: "move_card", cardId: "subject_card", toZone: "battlefield", underControlOf: "controller" }],
    });
  });

  const put = (game: GameState, ownerId: string, definition: CardDefinition) => {
    game.definitions[definition.id] = definition;
    const card = createCardInstance({ definitionId: definition.id, ownerId, zone: "battlefield" });
    card.summoningSick = false;
    game.cards[card.id] = card;
    game.players.find((e) => e.id === ownerId)!.zones.battlefield.push(card.id);
    return card.id;
  };

  it("reanimates a creature card milled from the library", () => {
    const { game, p1 } = twoPlayers();
    fillLibraries(game, 5);
    put(game, p1.id, compileReaver().definition);
    // A creature card on top of the library.
    const bearDef = createCardDefinition({ name: "Bear", typeLine: "Creature — Bear", manaCost: "{1}{G}", power: 2, toughness: 2 });
    game.definitions[bearDef.id] = bearDef;
    const bear = createCardInstance({ definitionId: bearDef.id, ownerId: p1.id, zone: "library" });
    game.cards[bear.id] = bear;
    game.players.find((e) => e.id === p1.id)!.zones.library.unshift(bear.id); // top of library

    // Mill one: the Bear hits the graveyard from the library and the Reaver reanimates it.
    let next = applyEffects(game, [{ kind: "mill", playerId: p1.id, count: 1 }] as unknown as GameEffect[]);
    while (next.stack.length > 0) next = resolveTopOfStack(next);

    expect(next.cards[bear.id]?.zone).toBe("battlefield");
    expect(next.cards[bear.id]?.controllerId).toBe(p1.id);
  });
});

describe("wave 476: Grolnok, the Omnivore — mill a permanent to exile with a croak counter, then play it", () => {
  const compileGrolnok = () =>
    compileOracleCard({
      oracleId: "grolnok-the-omnivore", name: "Grolnok, the Omnivore", manaCost: "{2}{G}{U}",
      typeLine: "Legendary Creature — Frog", power: "4", toughness: "4", printedKeywords: [], imageUrl: "",
      oracleText:
        "Whenever a Frog you control attacks, mill three cards.\n" +
        "Whenever a permanent card is put into your graveyard from your library, exile it with a croak counter on it.\n" +
        "You may play lands and cast spells from among cards you own in exile with croak counters on them.",
    });

  it("compiles the mill, the mill-to-exile croak, and the play-from-exile static", () => {
    const c = compileGrolnok();
    expect(c.notes).toEqual([]);
    expect(c.definition.playExiledWithCroakCounters).toBe(true);
    expect(c.definition.triggers?.[1]).toMatchObject({
      event: "graveyard_from_elsewhere",
      subjectFilter: { nonTypes: ["instant", "sorcery"] },
      effects: [{ kind: "croak_exile_grant", casterId: "controller" }],
    });
  });

  const put = (game: GameState, ownerId: string, definition: CardDefinition) => {
    game.definitions[definition.id] = definition;
    const card = createCardInstance({ definitionId: definition.id, ownerId, zone: "battlefield" });
    card.summoningSick = false;
    game.cards[card.id] = card;
    game.players.find((e) => e.id === ownerId)!.zones.battlefield.push(card.id);
    return card.id;
  };
  const topOfLibrary = (game: GameState, ownerId: string, definition: CardDefinition) => {
    game.definitions[definition.id] = definition;
    const card = createCardInstance({ definitionId: definition.id, ownerId, zone: "library" });
    game.cards[card.id] = card;
    game.players.find((e) => e.id === ownerId)!.zones.library.unshift(card.id);
    return card.id;
  };

  it("exiles a milled permanent with a croak counter and lets its owner cast it from exile", () => {
    const { game, p1 } = twoPlayers();
    fillLibraries(game, 5);
    put(game, p1.id, compileGrolnok().definition);
    const bearId = topOfLibrary(game, p1.id, createCardDefinition({ name: "Bear", typeLine: "Creature — Bear", manaCost: "{1}{G}", power: 2, toughness: 2 }));

    let next = applyEffects(game, [{ kind: "mill", playerId: p1.id, count: 1 }] as unknown as GameEffect[]);
    while (next.stack.length > 0) next = resolveTopOfStack(next);

    // Exiled from the graveyard with a croak counter and a play-from-exile grant.
    expect(next.cards[bearId]?.zone).toBe("exile");
    expect(next.cards[bearId]?.counters.croak).toBe(1);
    expect(next.exilePlayable?.find((g) => g.cardId === bearId)).toMatchObject({ casterId: p1.id, whileExiled: true });

    // In a main phase with {G}{G} the owner casts the exiled Bear.
    const ready = advanceSteps(next, 3);
    ready.priorityPlayerId = p1.id;
    ready.players[0]!.mana = { W: 0, U: 0, B: 0, R: 0, G: 2, C: 0 };
    expect(legalActions(ready, p1.id).some((a) => a.kind === "cast_spell" && a.cardId === bearId)).toBe(true);
  });

  it("does not exile a milled instant (the nonpermanent filter excludes it)", () => {
    const { game, p1 } = twoPlayers();
    fillLibraries(game, 5);
    put(game, p1.id, compileGrolnok().definition);
    const boltId = topOfLibrary(game, p1.id, createCardDefinition({ name: "Bolt", typeLine: "Instant", manaCost: "{R}" }));

    let next = applyEffects(game, [{ kind: "mill", playerId: p1.id, count: 1 }] as unknown as GameEffect[]);
    while (next.stack.length > 0) next = resolveTopOfStack(next);

    // The instant just sits in the graveyard.
    expect(next.cards[boltId]?.zone).toBe("graveyard");
  });
});

describe("wave 477: Hedge Shredder / Crew — tap a creature to turn the Vehicle into a creature", () => {
  const compileShredder = () =>
    compileOracleCard({
      oracleId: "hedge-shredder", name: "Hedge Shredder", manaCost: "{2}{G}{G}", typeLine: "Artifact — Vehicle",
      power: "4", toughness: "4", printedKeywords: [], imageUrl: "",
      oracleText:
        "Whenever this Vehicle attacks, you may mill two cards.\n" +
        "Whenever one or more land cards are put into your graveyard from your library, put them onto the battlefield tapped.\n" +
        "Crew 1 (Tap any number of creatures you control with total power 1 or more: This Vehicle becomes an artifact creature until end of turn.)",
    });

  it("compiles the mill triggers and the Crew activated ability", () => {
    const c = compileShredder();
    expect(c.notes).toEqual([]);
    expect(c.definition.triggers?.map((t) => t.event)).toEqual(["attacks", "graveyard_from_elsewhere"]);
    expect(c.definition.activated?.[0]).toMatchObject({
      costTapCreatureOther: true, crewPower: 1,
      effects: [{ kind: "become_creature_until_eot", cardId: "self" }],
    });
  });

  const put = (game: GameState, ownerId: string, definition: CardDefinition) => {
    game.definitions[definition.id] = definition;
    const card = createCardInstance({ definitionId: definition.id, ownerId, zone: "battlefield" });
    card.summoningSick = false;
    game.cards[card.id] = card;
    game.players.find((e) => e.id === ownerId)!.zones.battlefield.push(card.id);
    return card.id;
  };
  const isCreatureNow = (g: GameState, id: string) => characteristicsOf(g, id).types.includes("creature");

  it("crewing taps a creature and the Vehicle becomes a 4/4 artifact creature", () => {
    const { game, p1 } = twoPlayers();
    const shredder = put(game, p1.id, compileShredder().definition);
    const bearId = put(game, p1.id, createCardDefinition({ name: "Bear", typeLine: "Creature — Bear", manaCost: "{1}{G}", power: 2, toughness: 2 }));
    game.priorityPlayerId = p1.id;

    expect(isCreatureNow(game, shredder)).toBe(false); // a Vehicle is not a creature until crewed
    let act = applyAction(game, { kind: "activate_ability", playerId: p1.id, cardId: shredder, abilityIndex: 0, targets: [], costTapCreatureId: bearId });
    while (act.stack.length > 0) act = resolveTopOfStack(act);

    // The Bear is tapped (the crew cost), and the Vehicle is now an artifact creature at its printed 4/4.
    expect(act.cards[bearId]?.tapped).toBe(true);
    expect(isCreatureNow(act, shredder)).toBe(true);
    expect(characteristicsOf(act, shredder).types).toContain("artifact");
    expect(creaturePower(act, shredder)).toBe(4);
    expect(creatureToughness(act, shredder)).toBe(4);
  });

  it("a higher Crew number needs a creature that supplies the power", () => {
    const heavy = compileOracleCard({
      oracleId: "heavy-rig", name: "Heavy Rig", manaCost: "{4}", typeLine: "Artifact — Vehicle",
      power: "6", toughness: "6", printedKeywords: [], imageUrl: "", oracleText: "Crew 3",
    }).definition;
    const { game, p1 } = twoPlayers();
    const rig = put(game, p1.id, heavy);
    const weakId = put(game, p1.id, createCardDefinition({ name: "Cub", typeLine: "Creature — Bear", manaCost: "{G}", power: 2, toughness: 2 }));
    game.priorityPlayerId = p1.id;

    // A power-2 creature can't crew a Crew 3 Vehicle.
    expect(() =>
      applyAction(game, { kind: "activate_ability", playerId: p1.id, cardId: rig, abilityIndex: 0, targets: [], costTapCreatureId: weakId }),
    ).toThrow();
  });
});

describe("wave 478: Counterbalance — reveal the top card, counter a matching-cost spell", () => {
  const compileCB = () =>
    compileOracleCard({
      oracleId: "counterbalance", name: "Counterbalance", manaCost: "{U}{U}", typeLine: "Enchantment",
      power: null, toughness: null, printedKeywords: [], imageUrl: "",
      oracleText:
        "Whenever an opponent casts a spell, you may reveal the top card of your library. If you do, counter that spell if it has the same mana value as the revealed card.",
    });

  it("compiles the opponent-cast trigger with the counterbalance effect", () => {
    const c = compileCB();
    expect(c.notes).toEqual([]);
    expect(c.definition.triggers?.[0]).toMatchObject({
      event: "cast_spell", watch: "opponents", effects: [{ kind: "counterbalance" }],
    });
  });

  const put = (game: GameState, ownerId: string, definition: CardDefinition) => {
    game.definitions[definition.id] = definition;
    const card = createCardInstance({ definitionId: definition.id, ownerId, zone: "battlefield" });
    card.summoningSick = false;
    game.cards[card.id] = card;
    game.players.find((e) => e.id === ownerId)!.zones.battlefield.push(card.id);
    return card.id;
  };
  const topOf = (game: GameState, ownerId: string, definition: CardDefinition) => {
    game.definitions[definition.id] = definition;
    const card = createCardInstance({ definitionId: definition.id, ownerId, zone: "library" });
    game.cards[card.id] = card;
    game.players.find((e) => e.id === ownerId)!.zones.library.unshift(card.id);
    return card.id;
  };
  const inHand = (game: GameState, ownerId: string, definition: CardDefinition) => {
    game.definitions[definition.id] = definition;
    const card = createCardInstance({ definitionId: definition.id, ownerId, zone: "hand" });
    game.cards[card.id] = card;
    game.players.find((e) => e.id === ownerId)!.zones.hand.push(card.id);
    return card.id;
  };

  const setup = (topManaCost: string) => {
    const { game, p1, p2 } = twoPlayers();
    fillLibraries(game, 5);
    put(game, p1.id, compileCB().definition);
    topOf(game, p1.id, createCardDefinition({ name: "Top", typeLine: "Sorcery", manaCost: topManaCost }));
    // p2's spell is a {1}{R} (mana value 2) "You gain 3 life" instant.
    const spellId = inHand(game, p2.id, createCardDefinition({ name: "Solace", typeLine: "Instant", manaCost: "{1}{R}" }));
    game.definitions[game.cards[spellId]!.definitionId]!.oracleText = "You gain 3 life.";
    game.definitions[game.cards[spellId]!.definitionId]!.effects = [
      { kind: "gain_life", playerId: p2.id, amount: 3 },
    ] as unknown as typeof game.definitions[string]["effects"];
    game.priorityPlayerId = p2.id;
    game.players.find((e) => e.id === p2.id)!.mana = { W: 0, U: 0, B: 0, R: 2, G: 0, C: 0 };
    return { game, p1, p2, spellId };
  };

  it("counters the spell when the revealed card shares its mana value (its effect never happens)", () => {
    const { game, p2, spellId } = setup("{1}{G}"); // top MV 2 == spell MV 2
    const lifeBefore = game.players.find((e) => e.id === p2.id)!.life;
    let next = applyAction(game, { kind: "cast_spell", playerId: p2.id, cardId: spellId, targets: [] });
    while (next.stack.length > 0) next = resolveTopOfStack(next);
    expect(next.cards[spellId]?.zone).toBe("graveyard");
    // Countered -> no life gained.
    expect(next.players.find((e) => e.id === p2.id)!.life).toBe(lifeBefore);
  });

  it("lets the spell resolve (its effect happens) when the mana values differ", () => {
    const { game, p2, spellId } = setup("{2}{G}{G}"); // top MV 4 != spell MV 2
    const lifeBefore = game.players.find((e) => e.id === p2.id)!.life;
    let next = applyAction(game, { kind: "cast_spell", playerId: p2.id, cardId: spellId, targets: [] });
    while (next.stack.length > 0) next = resolveTopOfStack(next);
    expect(next.cards[spellId]?.zone).toBe("graveyard");
    // Not countered -> the spell resolved and its controller gained 3 life.
    expect(next.players.find((e) => e.id === p2.id)!.life).toBe(lifeBefore + 3);
  });
});
